'use strict';

// Regenerates the language pack's translation files from the installed Cursor's NLS
// catalogs, matching by English text so renamed NLS keys in new Cursor builds still
// get translated.

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const HEADER = [
	'--------------------------------------------------------------------------------------------',
	'Vietnamese Language Pack for Cursor. Generated from Cursor NLS catalogs.',
	'--------------------------------------------------------------------------------------------',
	'Do not edit this file. It is machine generated.',
];

function i18nFile(contents) {
	return JSON.stringify({ '': HEADER, version: '1.0.0', contents }, null, 2) + '\n';
}

function translateMap(map, dict) {
	const out = {};
	for (const [k, v] of Object.entries(map)) {
		out[k] = typeof v === 'string' && typeof dict[v] === 'string' ? dict[v] : v;
	}
	return out;
}

function buildMain(appRoot, dict) {
	const keys = JSON.parse(fs.readFileSync(path.join(appRoot, 'out', 'nls.keys.json'), 'utf8'));
	const msgs = JSON.parse(fs.readFileSync(path.join(appRoot, 'out', 'nls.messages.json'), 'utf8'));
	const contents = {};
	let i = 0;
	for (const [module, moduleKeys] of keys) {
		const bucket = {};
		for (const key of moduleKeys) {
			const en = msgs[i++];
			bucket[key] = typeof dict[en] === 'string' ? dict[en] : en;
		}
		contents[module] = bucket;
	}
	return i18nFile(contents);
}

function extensionNls(appRoot) {
	const result = new Map();
	const root = path.join(appRoot, 'extensions');
	if (!fs.existsSync(root)) {
		return result;
	}
	for (const name of fs.readdirSync(root)) {
		const nlsPath = path.join(root, name, 'package.nls.json');
		const pkgPath = path.join(root, name, 'package.json');
		if (!fs.existsSync(nlsPath) || !fs.existsSync(pkgPath)) {
			continue;
		}
		const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
		if (!pkg.name) {
			continue;
		}
		const id = pkg.publisher ? `${pkg.publisher}.${pkg.name}` : pkg.name;
		result.set(id, JSON.parse(fs.readFileSync(nlsPath, 'utf8')));
	}
	return result;
}

function writeIfChanged(file, text) {
	if (fs.existsSync(file) && fs.readFileSync(file, 'utf8') === text) {
		return false;
	}
	fs.mkdirSync(path.dirname(file), { recursive: true });
	fs.writeFileSync(file, text);
	return true;
}

// Rewrites translations in `extensionRoot` for the translation ids it contributes.
// Returns true when any file changed.
function sync({ appRoot, extensionRoot, dict }) {
	const pkg = JSON.parse(fs.readFileSync(path.join(extensionRoot, 'package.json'), 'utf8'));
	const translations = pkg.contributes.localizations[0].translations;
	const extNls = extensionNls(appRoot);
	let changed = false;
	for (const { id, path: rel } of translations) {
		const target = path.join(extensionRoot, rel);
		if (id === 'vscode') {
			changed = writeIfChanged(target, buildMain(appRoot, dict)) || changed;
		} else if (extNls.has(id)) {
			changed = writeIfChanged(target, i18nFile({ package: translateMap(extNls.get(id), dict) })) || changed;
		}
	}
	return changed;
}

// Cursor caches resolved translations per language pack hash and commit; drop the cache
// for this commit so regenerated files are picked up on the next start.
function clearCache(userDataDir, commit) {
	const clp = path.join(userDataDir, 'clp');
	if (!fs.existsSync(clp)) {
		return;
	}
	for (const entry of fs.readdirSync(clp)) {
		if (entry.endsWith('.vi')) {
			fs.rmSync(path.join(clp, entry, commit), { recursive: true, force: true });
		}
	}
}

function digest(text) {
	return crypto.createHash('sha256').update(text).digest('hex');
}

module.exports = { sync, clearCache, digest };
